def shift():
    if not out_stack:
        while in_stack:
            out_stack.append(in_stack.pop())
for _ in range(q):
    parts = input().split()
    if parts[0] == 'push':
        in_stack.append(parts[1])
    else:
        shift()
        if not out_stack:
            print('EMPTY')
