    for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) scanf("%d", &a[i][j]);
    for (int i = 0; i < r; i++) {
        int col = 0;
        for (int j = 1; j < c; j++) if (a[i][j] < a[i][col]) col = j;
        int ok = 1;
        for (int k = 0; k < r; k++) if (a[k][col] > a[i][col]) ok = 0;
        if (ok) {
            printf("Saddle point: %d at (%d, %d)\n", a[i][col], i, col);
            return 0;
        }
    }
    printf("No saddle point\n");
    return 0;
}

