int main(void) {
    int r, c, a[50][50];
    scanf("%d %d", &r, &c);
    for (int i = 0; i < r; i++) for (int j = 0; j < c; j++) scanf("%d", &a[i][j]);
    int top = 0, bottom = r - 1, left = 0, right = c - 1, first = 1;
    while (top <= bottom && left <= right) {
        for (int j = left; j <= right; j++) { printf("%s%d", first ? "" : " ", a[top][j]); first = 0; }
        top++;
        for (int i = top; i <= bottom; i++) printf(" %d", a[i][right]);
        right--;
        if (top <= bottom) { for (int j = right; j >= left; j--) printf(" %d", a[bottom][j]); bottom--; }
        if (left <= right) { for (int i = bottom; i >= top; i--) printf(" %d", a[i][left]); left++; }
    }
    printf("\n");
    return 0;
}

