    scanf("%d", &flag);
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    sortWith(a, n, flag ? descending : ascending);
    for (int i = 0; i < n; i++) printf("%d%s", a[i], i < n - 1 ? " " : "");
    printf("\n");
    return 0;
}

