    size_t cap = 8, len = 0;
    char *buf = malloc(cap);
    while ((c = getchar()) != EOF) {
        if (c == '\n') {
            printf("Line %d: %zu\n", ++lineNo, len);
            len = 0;
            continue;
        }
        if (len + 1 >= cap) {
            cap *= 2;
            buf = realloc(buf, cap);
        }
        buf[len++] = c;
    }
    if (len > 0) printf("Line %d: %zu\n", ++lineNo, len);
    free(buf);
    return 0;
}

