#include <stdio.h>

struct Account {
    int balance;
};

void deposit(struct Account *a, int amount) {
    a->balance += amount;
}

int withdraw(struct Account *a, int amount) {
    if (amount > a->balance) return 0;
    a->balance -= amount;
    return 1;
}

int main(void) {
    struct Account a;
    scanf("%d", &a.balance);
    int n;
    scanf("%d", &n);
    while (n--) {
        char op;
        int amount;
        scanf(" %c %d", &op, &amount);
        if (op == 'D') deposit(&a, amount);
        else if (!withdraw(&a, amount)) printf("Insufficient funds\n");
    }
    printf("Balance: %d\n", a.balance);
    return 0;
}

