#include <stddef.h>

size_t bytesInUse = 0;

void *tracked(size_t n) {
    bytesInUse += n;
    return malloc(n);
}

void release(void *p, size_t n) {
    bytesInUse -= n;
    free(p);
}

int main(void) {
    int n;
    scanf("%d", &n);
    void *blocks[100];
    size_t sizes[100], released = 0, total = 0;
    for (int i = 0; i < n; i++) {
        scanf("%zu", &sizes[i]);
        blocks[i] = tracked(sizes[i]);
        total += sizes[i];
    }
    for (int i = 1; i < n; i += 2) { release(blocks[i], sizes[i]); blocks[i] = NULL; released += sizes[i]; }
    printf("Allocated: %zu\nReleased: %zu\nIn use: %zu\n", total, released, bytesInUse);
    for (int i = 0; i < n; i++) free(blocks[i]);
    return 0;
}

