    if (count == 0) printf("Empty\n");
    else {
        printf("Names:");
        for (int i = 0; i < count; i++) printf(" %s", names[i]);
        printf("\n");
    }
    printf("Count: %d\nCapacity: %d\n", count, cap);
    free(names);
