    int h, m;
    Time(int h, int m) {
        this.h = h;
        this.m = m;
    }
    Time add(Time o) {
        int total = (h + o.h) * 60 + m + o.m;
        return new Time(total / 60, total % 60);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int h1 = in.nextInt(), m1 = in.nextInt(), h2 = in.nextInt(), m2 = in.nextInt();
        Time t = new Time(h1, m1).add(new Time(h2, m2));
        System.out.printf("%02d:%02d%n", t.h, t.m);
    }
}

