class Student implements Comparable<Student> {
    String name;
    int marks;
    Student(String name, int marks) {
        this.name = name;
        this.marks = marks;
    }
    public int compareTo(Student o) {
        if (marks != o.marks) return Integer.compare(o.marks, marks);
        return name.compareTo(o.name);
    }
}

