class MyStack<T> {
    private final List<T> items = new ArrayList<>();
    void push(T x) {
        items.add(x);
    }
    T pop() {
        return items.isEmpty() ? null : items.remove(items.size() - 1);
    }
    boolean isEmpty() {
        return items.isEmpty();
    }
}

