import java.util.*;

class Node {
    int value;
    Node next;
    Node(int value) {
        this.value = value;
    }
}

class MyList {
    Node head, tail;
    void addFirst(int x) {
        Node n = new Node(x);
        n.next = head;
        head = n;
        if (tail == null) tail = n;
    }
    void addLast(int x) {
        Node n = new Node(x);
        if (tail == null) head = n;
        else tail.next = n;
        tail = n;
    }
    public String toString() {
        if (head == null) return "Empty";
        StringBuilder sb = new StringBuilder();
        for (Node p = head; p != null; p = p.next) sb.append(p.value).append(p.next != null ? " -> " : "");
        return sb.toString();
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        MyList list = new MyList();
        while (n-- > 0) {
            char where = in.next().charAt(0);
            int x = in.nextInt();
            if (where == 'F') list.addFirst(x);
            else list.addLast(x);
        }
        System.out.println(list);
    }
}

