import java.util.*;

class MyQueue<T> {
    private class Cell {
        T value;
        Cell next;
        Cell(T value) {
            this.value = value;
        }
    }
    private Cell head, tail;
    private int size;
    void enqueue(T x) {
        Cell c = new Cell(x);
        if (tail == null) head = c;
        else tail.next = c;
        tail = c;
        size++;
    }
    T dequeue() {
        if (head == null) return null;
        T v = head.value;
        head = head.next;
        if (head == null) tail = null;
        size--;
        return v;
    }
    int size() {
        return size;
    }
}

