import java.util.*;

class SafeStack {
    private final LinkedList<Integer> items = new LinkedList<>();
    synchronized void push(int x) {
        items.addFirst(x);
    }
    synchronized Integer pop() {
        return items.isEmpty() ? null : items.removeFirst();
    }
    synchronized int size() {
        return items.size();
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int t = in.nextInt(), m = in.nextInt();
        SafeStack st = new SafeStack();
        Thread[] ts = new Thread[t];
        for (int k = 0; k < t; k++) {
            ts[k] = new Thread(() -> {
                for (int i = 1; i <= m; i++) st.push(i);
            });
            ts[k].start();
        }
        for (Thread x : ts) x.join();
        System.out.println("Size: " + st.size());
        long sum = 0;
        Integer v;
        while ((v = st.pop()) != null) sum += v;
        System.out.println("Sum: " + sum);
    }
}

