import java.util.*;

class Registry {
    private static volatile Registry instance;
    private Registry() {
    }
    static Registry get() {
        if (instance == null) {
            synchronized (Registry.class) {
                if (instance == null) instance = new Registry();
            }
        }
        return instance;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
