        Thread[] ts = new Thread[n];
        for (int i = 0; i < n; i++) {
            final int id = i;
            ts[i] = new Thread(() -> got[id] = Registry.get());
            ts[i].start();
        }
        for (Thread t : ts) t.join();
        System.out.println("Unique instances: " + new HashSet<>(Arrays.asList(got)).size());
    }
}

