import java.util.*;
import java.util.concurrent.*;

class MiniPool {
    private static final Runnable STOP = () -> {
    };
    private final BlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();
    private final Thread[] workers;
    MiniPool(int n) {
        workers = new Thread[n];
        for (int i = 0; i < n; i++) {
            workers[i] = new Thread(() -> {
                try {
                    while (true) {
                        Runnable task = queue.take();
                        if (task == STOP) return;
                        task.run();
                    }
                } catch (InterruptedException e) {
                }
            });
            workers[i].start();
        }
    }
    void submit(Runnable r) {
        queue.add(r);
    }
    void shutdownAndWait() throws InterruptedException {
        for (int i = 0; i < workers.length; i++) queue.add(STOP);
        for (Thread t : workers) t.join();
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int w = in.nextInt(), n = in.nextInt();
        MiniPool pool = new MiniPool(w);
        int[] result = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            final int x = i;
            pool.submit(() -> result[x] = x * x);
        }
        pool.shutdownAndWait();
        for (int i = 1; i <= n; i++) System.out.println("Result " + i + ": " + result[i]);
    }
}

