import java.util.*;

class Acct {
    final int id;
    int balance;
    Acct(int id, int balance) {
        this.id = id;
        this.balance = balance;
    }
    static void transfer(Acct from, Acct to, int amount) {
        Acct first = from.id < to.id ? from : to, second = first == from ? to : from;
        synchronized (first) {
            synchronized (second) {
                from.balance -= amount;
                to.balance += amount;
            }
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int a = in.nextInt(), b = in.nextInt(), m = in.nextInt();
        Acct x = new Acct(1, a), y = new Acct(2, b);
        Thread t1 = new Thread(() -> {
            for (int i = 0; i < m; i++) Acct.transfer(x, y, 1);
        });
        Thread t2 = new Thread(() -> {
            for (int i = 0; i < m; i++) Acct.transfer(y, x, 1);
        });
        t1.start();
        t2.start();
        t1.join();
        t2.join();
        System.out.println("Account 1: " + x.balance);
        System.out.println("Account 2: " + y.balance);
    }
}

