public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int w = in.nextInt(), n = in.nextInt();
        int[] part = new int[w];
        Thread[] ts = new Thread[w];
        for (int k = 0; k < w; k++) {
            final int id = k;
            ts[k] = new Thread(() -> {
                for (int i = 2; i <= n; i++) {
                    if (i % w != id) continue;
                    boolean prime = true;
                    for (int d = 2; (long) d * d <= i; d++) if (i % d == 0) { prime = false; break; }
                    if (prime) part[id]++;
                }
            });
            ts[k].start();
        }
        for (Thread t : ts) t.join();
        int total = 0;
        for (int c : part) total += c;
        System.out.println("Primes up to " + n + ": " + total);
    }
}

