import java.util.*;
import java.util.concurrent.*;

class SortTask extends RecursiveTask<int[]> {
    private final int[] a;
    SortTask(int[] a) {
        this.a = a;
    }
    protected int[] compute() {
        if (a.length <= 1) return a;
        int mid = a.length / 2;
        SortTask left = new SortTask(Arrays.copyOfRange(a, 0, mid)), right = new SortTask(Arrays.copyOfRange(a, mid, a.length));
        left.fork();
        int[] r = right.compute(), l = left.join();
        int[] out = new int[a.length];
        int i = 0, j = 0, k = 0;
        while (i < l.length && j < r.length) out[k++] = l[i] <= r[j] ? l[i++] : r[j++];
        while (i < l.length) out[k++] = l[i++];
        while (j < r.length) out[k++] = r[j++];
        return out;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();
        int[] sorted = new ForkJoinPool().invoke(new SortTask(a));
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < sorted.length; i++) sb.append(sorted[i]).append(i < sorted.length - 1 ? " " : "");
        System.out.println(sb);
    }
}

