import java.util.*;

class Light {
    private int turn = 0;
    synchronized void pass(int who, String name) {
        while (turn != who) {
            try {
                wait();
            } catch (InterruptedException e) {
                return;
            }
        }
        System.out.println(name + " passes");
        turn = 1 - turn;
        notifyAll();
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Light light = new Light();
        Thread ns = new Thread(() -> {
            for (int i = 0; i < n; i++) light.pass(0, "North-South");
        });
        Thread ew = new Thread(() -> {
            for (int i = 0; i < n; i++) light.pass(1, "East-West");
        });
        ns.start();
        ew.start();
        ns.join();
        ew.join();
        System.out.println("Cycles: " + n);
    }
}

