import java.util.*;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;

class Secret implements Serializable {
    private static final long serialVersionUID = 1L;
    transient String text;
    Secret(String text) {
        this.text = text;
    }
    private void writeObject(ObjectOutputStream out) throws IOException {
        out.defaultWriteObject();
        out.writeObject(new StringBuilder(text).reverse().toString());
    }
    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        in.defaultReadObject();
        text = new StringBuilder((String) in.readObject()).reverse().toString();
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        String w = in.next();
        File f = new File("secret.ser");
        try (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(f))) {
            out.writeObject(new Secret(w));
        }
        String raw = new String(Files.readAllBytes(f.toPath()), StandardCharsets.ISO_8859_1);
        String reversed = new StringBuilder(w).reverse().toString();
        try (ObjectInputStream inp = new ObjectInputStream(new FileInputStream(f))) {
            System.out.println("Restored: " + ((Secret) inp.readObject()).text);
        }
        System.out.println("File holds reversed text: " + raw.contains(reversed));
        f.delete();
    }
}

