import java.util.*;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Path root = Paths.get("tree");
        Files.createDirectories(root.resolve("sub/deep"));
        Files.write(root.resolve("a.txt"), "a".getBytes());
        Files.write(root.resolve("sub/b.txt"), "b".getBytes());
        Files.write(root.resolve("sub/deep/c.txt"), "c".getBytes());
        List<String> files = new ArrayList<>();
        try (java.util.stream.Stream<Path> walk = Files.walk(root)) {
            walk.filter(Files::isRegularFile).forEach(p -> files.add(root.relativize(p).toString().replace(File.separatorChar, '/')));
        }
        Collections.sort(files);
        for (String f : files) System.out.println(f);
        System.out.println("Files: " + files.size());
        try (java.util.stream.Stream<Path> walk = Files.walk(root)) {
            List<Path> all = new ArrayList<>();
            walk.forEach(all::add);
            Collections.reverse(all);
            for (Path p : all) Files.delete(p);
        }
    }
}

