import java.util.*;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        Path dir = Paths.get("watch");
        Files.createDirectories(dir);
        String[] start = in.nextLine().trim().split("\\s+"), add = in.nextLine().trim().split("\\s+"), remove = in.nextLine().trim().split("\\s+");
        for (String n : start) if (!n.equals("-")) Files.write(dir.resolve(n), new byte[0]);
        Set<String> before = new TreeSet<>(Arrays.asList(dir.toFile().list()));
        for (String n : add) if (!n.equals("-")) Files.write(dir.resolve(n), new byte[0]);
        for (String n : remove) if (!n.equals("-")) Files.deleteIfExists(dir.resolve(n));
        Set<String> after = new TreeSet<>(Arrays.asList(dir.toFile().list()));
        Set<String> created = new TreeSet<>(after), deleted = new TreeSet<>(before);
        created.removeAll(before);
        deleted.removeAll(after);
        System.out.println("Created: " + (created.isEmpty() ? "none" : String.join(" ", created)));
        System.out.println("Deleted: " + (deleted.isEmpty() ? "none" : String.join(" ", deleted)));
        for (File f : dir.toFile().listFiles()) f.delete();
        Files.delete(dir);
    }
}

