public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        String s = in.nextLine();
        File f = new File("unzip.zip");
        try (ZipOutputStream out = new ZipOutputStream(new FileOutputStream(f))) {
            out.putNextEntry(new ZipEntry("note.txt"));
            out.write(s.getBytes(StandardCharsets.UTF_8));
            out.closeEntry();
        }
        try (ZipInputStream zin = new ZipInputStream(new FileInputStream(f))) {
            ZipEntry e = zin.getNextEntry();
            ByteArrayOutputStream buf = new ByteArrayOutputStream();
            byte[] chunk = new byte[256];
            int read;
            while ((read = zin.read(chunk)) > 0) buf.write(chunk, 0, read);
            System.out.println("Extracted " + e.getName() + ": " + new String(buf.toByteArray(), StandardCharsets.UTF_8));
        }
        f.delete();
    }
}

