import java.util.*;
import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class Main {
    static String ask(int port, String message) throws IOException {
        try (Socket c = new Socket("127.0.0.1", port);
             PrintWriter w = new PrintWriter(c.getOutputStream(), true);
             BufferedReader r = new BufferedReader(new InputStreamReader(c.getInputStream()))) {
            w.println(message);
            return r.readLine();
        }
    }

    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        String word = in.next();
        ServerSocket server = new ServerSocket(0);
        Thread t = new Thread(() -> {
            try (Socket s = server.accept();
                 BufferedReader r = new BufferedReader(new InputStreamReader(s.getInputStream()));
                 PrintWriter w = new PrintWriter(s.getOutputStream(), true)) {
                w.println("Echo: " + r.readLine());
            } catch (IOException e) {
            }
        });
        t.start();
        System.out.println("Client received: " + ask(server.getLocalPort(), word));
        t.join();
        server.close();
    }
}

