import java.util.*;
import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String[] w = new String[n];
        for (int i = 0; i < n; i++) w[i] = in.next();
        ServerSocket server = new ServerSocket(0);
        List<String> received = Collections.synchronizedList(new ArrayList<>());
        Thread acceptor = new Thread(() -> {
            List<Thread> handlers = new ArrayList<>();
            try {
                for (int i = 0; i < n; i++) {
                    Socket s = server.accept();
                    Thread h = new Thread(() -> {
                        try (s; BufferedReader r = new BufferedReader(new InputStreamReader(s.getInputStream()))) {
                            received.add(r.readLine());
                        } catch (IOException e) {
                        }
                    });
                    h.start();
                    handlers.add(h);
                }
                for (Thread h : handlers) h.join();
            } catch (Exception e) {
            }
        });
        acceptor.start();
        Thread[] clients = new Thread[n];
        for (int i = 0; i < n; i++) {
            final String msg = w[i];
            clients[i] = new Thread(() -> {
                try (Socket c = new Socket("127.0.0.1", server.getLocalPort());
                     PrintWriter out = new PrintWriter(c.getOutputStream(), true)) {
                    out.println(msg);
                } catch (IOException e) {
                }
            });
            clients[i].start();
        }
        for (Thread c : clients) c.join();
        acceptor.join();
        server.close();
        Collections.sort(received);
        System.out.println("Server received " + received.size() + " messages");
        for (String m : received) System.out.println(m);
    }
}

