import java.util.*;
import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import com.sun.net.httpserver.HttpServer;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        String name = in.next();
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/hello", ex -> {
            String q = ex.getRequestURI().getQuery();
            String who = q != null && q.startsWith("name=") ? q.substring(5) : "stranger";
            byte[] body = ("Hello, " + who + "!").getBytes(StandardCharsets.UTF_8);
            ex.sendResponseHeaders(200, body.length);
            try (OutputStream o = ex.getResponseBody()) {
                o.write(body);
            }
        });
        server.start();
        URL url = new URL("http://127.0.0.1:" + server.getAddress().getPort() + "/hello?name=" + name);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        System.out.println("Status: " + conn.getResponseCode());
        try (BufferedReader r = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {
            System.out.println("Body: " + r.readLine());
        }
        server.stop(0);
    }
}

