import java.util.*;
import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import com.sun.net.httpserver.HttpServer;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        String s = in.nextLine();
        String html = "<html><head><title>" + s + "</title></head><body>Hi</body></html>";
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/", ex -> {
            byte[] body = html.getBytes(StandardCharsets.UTF_8);
            ex.getResponseHeaders().add("Content-Type", "text/html");
            ex.sendResponseHeaders(200, body.length);
            try (OutputStream o = ex.getResponseBody()) {
                o.write(body);
            }
        });
        server.start();
        HttpURLConnection conn = (HttpURLConnection) new URL("http://127.0.0.1:" + server.getAddress().getPort() + "/").openConnection();
        int status = conn.getResponseCode();
        StringBuilder sb = new StringBuilder();
        try (BufferedReader r = new BufferedReader(new InputStreamReader(conn.getInputStream()))) {
            int ch;
            while ((ch = r.read()) != -1) sb.append((char) ch);
        }
        String page = sb.toString();
        System.out.println("Status: " + status);
        System.out.println("Length: " + page.length());
        System.out.println("Title: " + page.substring(page.indexOf("<title>") + 7, page.indexOf("</title>")));
        server.stop(0);
    }
}

