import java.util.*;
import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        String word = in.next();
        DatagramSocket serverSocket = new DatagramSocket(0, InetAddress.getByName("127.0.0.1"));
        String[] got = new String[1];
        Thread t = new Thread(() -> {
            try {
                byte[] buf = new byte[256];
                DatagramPacket p = new DatagramPacket(buf, buf.length);
                serverSocket.receive(p);
                got[0] = new String(p.getData(), 0, p.getLength(), StandardCharsets.UTF_8);
                byte[] reply = got[0].toUpperCase().getBytes(StandardCharsets.UTF_8);
                serverSocket.send(new DatagramPacket(reply, reply.length, p.getAddress(), p.getPort()));
            } catch (IOException e) {
            }
        });
        t.start();
        try (DatagramSocket client = new DatagramSocket()) {
            byte[] out = word.getBytes(StandardCharsets.UTF_8);
            client.send(new DatagramPacket(out, out.length, InetAddress.getByName("127.0.0.1"), serverSocket.getLocalPort()));
            client.setSoTimeout(5000);
            DatagramPacket in2 = new DatagramPacket(new byte[256], 256);
            client.receive(in2);
        }
        t.join();
        System.out.println("Server got: " + got[0]);
        serverSocket.close();
    }
}

