import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;

public class Main {
    static String send(int port, String text) throws IOException {
        try (DatagramSocket s = new DatagramSocket()) {
            byte[] out = text.getBytes(StandardCharsets.UTF_8);
            s.send(new DatagramPacket(out, out.length, InetAddress.getByName("127.0.0.1"), port));
            s.setSoTimeout(5000);
            DatagramPacket p = new DatagramPacket(new byte[256], 256);
            s.receive(p);
            return new String(p.getData(), 0, p.getLength(), StandardCharsets.UTF_8);
        }
    }

    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        String word = in.next();
        DatagramSocket server = new DatagramSocket(0, InetAddress.getByName("127.0.0.1"));
        Thread t = new Thread(() -> {
            try {
                DatagramPacket p = new DatagramPacket(new byte[256], 256);
                server.receive(p);
                byte[] reply = ("Echo: " + new String(p.getData(), 0, p.getLength(), StandardCharsets.UTF_8)).getBytes(StandardCharsets.UTF_8);
                server.send(new DatagramPacket(reply, reply.length, p.getAddress(), p.getPort()));
            } catch (IOException e) {
            }
        });
        t.start();
        System.out.println("Reply: " + send(server.getLocalPort(), word));
        t.join();
        server.close();
    }
}

