import java.util.*;

class GQueue<T> {
    private final LinkedList<T> items = new LinkedList<>();
    void enqueue(T x) {
        items.addLast(x);
    }
    T dequeue() {
        return items.pollFirst();
    }
    int size() {
        return items.size();
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();
        GQueue<Integer> q = new GQueue<>();
        for (int x : a) q.enqueue(x);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 2; i++) {
            Integer v = q.dequeue();
            if (v != null) sb.append(sb.length() > 0 ? " " : "").append(v);
        }
        System.out.println("Dequeued: " + sb);
        System.out.println("Left: " + q.size());
    }
}

