import java.util.*;

class KV<K, V> {
    K key;
    V value;
    KV<K, V> next;
    KV(K key, V value) {
        this.key = key;
        this.value = value;
    }
}

class ChainMap<K, V> {
    private KV<K, V> head, tail;
    void put(K key, V value) {
        for (KV<K, V> p = head; p != null; p = p.next) {
            if (p.key.equals(key)) {
                p.value = value;
                return;
            }
        }
        KV<K, V> node = new KV<>(key, value);
        if (tail == null) head = node;
        else tail.next = node;
        tail = node;
    }
    V get(K key) {
        for (KV<K, V> p = head; p != null; p = p.next) if (p.key.equals(key)) return p.value;
        return null;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        ChainMap<String, Integer> map = new ChainMap<>();
        for (int i = 0; i < n; i++) map.put(in.next(), in.nextInt());
        Integer v = map.get(in.next());
        System.out.println(v == null ? "missing" : String.valueOf(v));
    }
}

