import java.util.*;
import java.util.Optional;

interface Repository<T, ID> {
    void save(T item);
    Optional<T> findById(ID id);
    int count();
}

class Student {
    final int id;
    final String name;
    Student(int id, String name) {
        this.id = id;
        this.name = name;
    }
}

class StudentRepo implements Repository<Student, Integer> {
    private final Map<Integer, Student> store = new LinkedHashMap<>();
    public void save(Student s) {
        store.put(s.id, s);
    }
    public Optional<Student> findById(Integer id) {
        return Optional.ofNullable(store.get(id));
    }
    public int count() {
        return store.size();
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        StudentRepo repo = new StudentRepo();
        for (int i = 0; i < n; i++) repo.save(new Student(in.nextInt(), in.next()));
        int q = in.nextInt();
        while (q-- > 0) {
            int id = in.nextInt();
            System.out.println(id + ": " + repo.findById(id).map(s -> s.name).orElse("not found"));
        }
        System.out.println("Count: " + repo.count());
    }
}

