import java.util.*;
import java.util.function.Predicate;

public class Main {
    static <T> int countIf(List<T> list, Predicate<T> test) {
        int count = 0;
        for (T x : list) if (test.test(x)) count++;
        return count;
    }

    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        List<Integer> nums = new ArrayList<>();
        List<String> words = new ArrayList<>();
        for (int i = 0; i < n; i++) nums.add(in.nextInt());
        for (int i = 0; i < n; i++) words.add(in.next());
        System.out.println("Even: " + countIf(nums, x -> x % 2 == 0));
        System.out.println("Positive: " + countIf(nums, x -> x > 0));
        System.out.println("Long words: " + countIf(words, s -> s.length() > 3));
    }
}

