import java.util.*;

class BST<T extends Comparable<T>> {
    private class Node {
        T value;
        Node left, right;
        Node(T value) {
            this.value = value;
        }
    }
    private Node root;
    void insert(T x) {
        root = insert(root, x);
    }
    private Node insert(Node n, T x) {
        if (n == null) return new Node(x);
        if (x.compareTo(n.value) < 0) n.left = insert(n.left, x);
        else n.right = insert(n.right, x);
        return n;
    }
    List<T> inOrder() {
        List<T> out = new ArrayList<>();
        walk(root, out);
        return out;
    }
    private void walk(Node n, List<T> out) {
        if (n == null) return;
        walk(n.left, out);
        out.add(n.value);
        walk(n.right, out);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        BST<Integer> a = new BST<>();
        BST<String> b = new BST<>();
        for (int i = 0; i < n; i++) a.insert(in.nextInt());
        for (int i = 0; i < n; i++) b.insert(in.next());
        System.out.println(a.inOrder().toString().replaceAll("[\\[\\],]", ""));
        System.out.println(b.inOrder().toString().replaceAll("[\\[\\],]", ""));
    }
}

