import java.util.*;

class Maybe<T> {
    private final T value;
    Maybe(T value) {
        this.value = value;
    }
    boolean isPresent() {
        return value != null;
    }
    T orElse(T other) {
        return value != null ? value : other;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        String a = in.next(), b = in.next();
        for (String s : new String[] {a, b}) {
            Maybe<String> m = new Maybe<>(s.equals("null") ? null : s);
            System.out.println(s + ": present=" + m.isPresent() + ", value=" + m.orElse("none"));
        }
    }
}

