public class Main {
    static <T extends Number & Comparable<T>> T biggest(List<T> list) {
        T best = list.get(0);
        for (T x : list) if (x.compareTo(best) > 0) best = x;
        return best;
    }

    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        List<Integer> ints = new ArrayList<>();
        List<Double> doubles = new ArrayList<>();
        for (int i = 0; i < n; i++) ints.add(in.nextInt());
        for (int i = 0; i < n; i++) doubles.add(in.nextDouble());
        System.out.println("Biggest int: " + biggest(ints));
        System.out.println("Biggest double: " + biggest(doubles));
    }
}

