import java.util.*;
import java.util.function.Consumer;

enum Level {
    INFO, WARN, ERROR
}

class Logger {
    private final Level min;
    private final List<Consumer<String>> handlers = new ArrayList<>();
    Logger(Level min) {
        this.min = min;
    }
    void addHandler(Consumer<String> h) {
        handlers.add(h);
    }
    void log(Level level, String text) {
        if (level.compareTo(min) < 0) return;
        for (Consumer<String> h : handlers) h.accept("[" + level + "] " + text);
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        Logger logger = new Logger(Level.valueOf(in.next()));
        int[] count = {0};
        logger.addHandler(System.out::println);
        logger.addHandler(msg -> count[0]++);
        int n = in.nextInt();
        for (int i = 0; i < n; i++) logger.log(Level.valueOf(in.next()), in.next());
        System.out.println("Handled: " + count[0]);
    }
}

