import java.util.*;
import java.util.function.*;

class Publisher<T> {
    private final List<Consumer<T>> subscribers = new ArrayList<>();
    void subscribe(Consumer<T> s) {
        subscribers.add(s);
    }
    void publish(T item) {
        for (Consumer<T> s : subscribers) s.accept(item);
    }
    Publisher<T> filter(Predicate<T> keep) {
        Publisher<T> next = new Publisher<>();
        subscribe(x -> {
            if (keep.test(x)) next.publish(x);
        });
        return next;
    }
    <R> Publisher<R> map(Function<T, R> f) {
        Publisher<R> next = new Publisher<>();
        subscribe(x -> next.publish(f.apply(x)));
        return next;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();
        Publisher<Integer> source = new Publisher<>();
        int[] count = {0};
        source.subscribe(x -> count[0]++);
        source.filter(x -> x % 2 == 0).map(x -> x * 10).subscribe(x -> System.out.println("Got " + x));
        for (int x : a) source.publish(x);
        System.out.println("Source items: " + count[0]);
    }
}

