import java.util.*;
import java.util.function.*;
import java.util.stream.*;

class Row {
    final String name;
    final int marks;
    Row(String name, int marks) {
        this.name = name;
        this.marks = marks;
    }
}

class Table<T> {
    private final List<T> rows;
    Table(List<T> rows) {
        this.rows = rows;
    }
    Table<T> where(Predicate<T> p) {
        return new Table<>(rows.stream().filter(p).collect(Collectors.toList()));
    }
    Table<T> orderBy(Comparator<T> c) {
        return new Table<>(rows.stream().sorted(c).collect(Collectors.toList()));
    }
    Table<T> limit(int k) {
        return new Table<>(rows.stream().limit(k).collect(Collectors.toList()));
    }
    <R> List<R> select(Function<T, R> f) {
        return rows.stream().map(f).collect(Collectors.toList());
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Locale.setDefault(Locale.US);
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        List<Row> rows = new ArrayList<>();
        for (int i = 0; i < n; i++) rows.add(new Row(in.next(), in.nextInt()));
        int min = in.nextInt(), k = in.nextInt();
        List<String> result = new Table<>(rows).where(r -> r.marks >= min).orderBy((x, y) -> x.marks != y.marks ? y.marks - x.marks : x.name.compareTo(y.name)).limit(k).select(r -> r.name + "(" + r.marks + ")");
        if (result.isEmpty()) System.out.println("No rows");
        for (String s : result) System.out.println(s);
    }
}

