def retry(times):
    def deco(fn):
        def wrapper():
            for k in range(1, times + 1):
                try:
                    return fn(k)
                except RuntimeError:
                    pass
            return "failed"

        return wrapper

    return deco


f, times = map(int, input().split())


@retry(times)
def service(attempt):
    if attempt <= f:
        raise RuntimeError("down")
    return f"success after {attempt} tries"


