class Car:
    def __init__(self, plate):
        self.plate = plate


class ParkingLot:
    def __init__(self, cap):
        self.cap = cap
        self.cars = []

    def park(self, plate):
        if len(self.cars) >= self.cap:
            return "Full"
        self.cars.append(Car(plate))
        return "Parked"

    def leave(self, plate):
        for c in self.cars:
            if c.plate == plate:
                self.cars.remove(c)
                return "Left"
        return "Not here"

    def free(self):
        return self.cap - len(self.cars)


cap, n = map(int, input().split())
lot = ParkingLot(cap)
for _ in range(n):
    c = input().split()
    if c[0] == "park":
        print(lot.park(c[1]))
    elif c[0] == "leave":
        print(lot.leave(c[1]))
    else:
        print(lot.free())

